/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
console.log(JSON.stringify({ node: process.version, platform: process.platform, arch: process.arch }));
for (const [args, code] of [
    [['sum', '6', '-1', '--json'], 0],
    [['sum', '6', 'abc', '--json'], 2],
    [['sum', '--json'], 2],
]) {
    const result = spawnSync(process.execPath, ['ops/tally.mjs', ...args], {
        encoding: 'utf8',
        stdio: ['ignore', 'pipe', 'pipe'],
        timeout: 5000,
    });
    if (result.error) throw result.error;
    console.log(JSON.stringify({ args, code: result.status, stdout: result.stdout, stderr: result.stderr }));
    assert.equal(result.status, code);
    if (code === 0) {
        assert.deepEqual(JSON.parse(result.stdout), { total: 5 });
        assert.equal(result.stderr, '');
    } else {
        assert.equal(result.stdout, '');
        assert.match(result.stderr, /\\S/);
    }
}
NODE"
